public class PooledBinaryWriter:System.IDisposable {public System.IO.BinaryWriter Writer;public void SetBaseStream(System.IO.Stream s){Writer=new System.IO.BinaryWriter(s,System.Text.Encoding.UTF8,true);}public void Write(byte value){Writer.Write(value);}public void Flush(){Writer.Flush();}public void Dispose(){Writer?.Dispose();}}
public class PooledBinaryReader:System.IDisposable {public System.IO.BinaryReader Reader;public void SetBaseStream(System.IO.Stream s){Reader=new System.IO.BinaryReader(s,System.Text.Encoding.UTF8,true);}public byte ReadByte(){return Reader.ReadByte();}public void Dispose(){Reader?.Dispose();}}
public class WriterPool {public PooledBinaryWriter AllocSync(bool value){return new PooledBinaryWriter();}}
public class ReaderPool {public PooledBinaryReader AllocSync(bool value){return new PooledBinaryReader();}}
public static class MemoryPools {public static WriterPool poolBinaryWriter=new WriterPool();public static ReaderPool poolBinaryReader=new ReaderPool();}
public class ItemValue {public int type;public string Data="";}
public class ItemStack {public int count;public ItemValue itemValue=new ItemValue();public void Write(PooledBinaryWriter w){w.Writer.Write((ushort)count);if(count==0)return;w.Writer.Write(itemValue.type);w.Writer.Write(itemValue.Data);}public ItemStack Read(PooledBinaryReader r){count=r.Reader.ReadUInt16();if(count>0){itemValue.type=r.Reader.ReadInt32();itemValue.Data=r.Reader.ReadString();}else itemValue=new ItemValue();return this;}}
public static class RebirthStationGridIngredients {public static bool IsSameStackSnapshot(ItemStack a,ItemStack b){return a.count==b.count&&a.itemValue.type==b.itemValue.type&&a.itemValue.Data==b.itemValue.Data;}}
public static class NativeInputFixture {static int checks;static void A(bool b,string n){checks++;if(!b)throw new System.Exception(n);}public static string Run(){var positive=new ItemStack{count=2,itemValue=new ItemValue{type=7,Data="metadata"}};A(RebirthStationNativeInputCodec.IsRoundTrippable(new[]{positive,new ItemStack()}),"ordinary native pair accepted");A(positive.count==2&&positive.itemValue.Data=="metadata","source untouched");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new[]{new ItemStack{count=0,itemValue=new ItemValue{type=7,Data="receipt"}}}),"zero count payload native loss refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new[]{new ItemStack{count=0,itemValue=new ItemValue{type=0,Data="receipt"}}}),"zero type hidden metadata loss refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new[]{new ItemStack{count=65536}}),"native count clamp refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new[]{new ItemStack{count=-1}}),"negative refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new ItemStack[]{null}),"null refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new ItemStack[10]),"oversized grid refused");A(!RebirthStationNativeInputCodec.IsRoundTrippable(new[]{new ItemStack{count=1,itemValue=new ItemValue{type=7,Data=new string('x',300000)}}}),"publication span cap enforced");return "PASS "+checks+" actual native-input preflight checks with explicit ItemStack/pool/comparison doubles; not actual native codec qualification";}}